private Response<AuthLoginResponse> loginForExternal(GatewayContext context, OperationEnum opertion) {
        Map<String, String> urlParam = GatewayContextUtil.appMap(context, null);
        AuthLoginRequest loginRequest = JSONObject.parseObject(context.getRequestBody(), AuthLoginRequest.class);
        loginRequest.setIpAddr(urlParam.get(AppClientConstants.USER_IP));
        Response<AuthLoginResponse> authLoginResponse = null;
        try {
            if (OperationEnum.AUTH_LOGIN == opertion) {
                authLoginResponse = passportLoginService.authLogin(loginRequest);
            }
            if (OperationEnum.PHONE_LOGIN == opertion) {
                authLoginResponse = passportLoginService.phoneLogin(loginRequest);
            }
        } catch (Exception e) {
            log.error("passportLoginService auth login has error", e);
            context.setResult(HttpResult.ofFailed(ResultCodeEnum.OUTSIDE_REMOTE_EXCEPTION));
            return null;
        }
        if (authLoginResponse == null) {
            log.error("passportLoginService auth is empty request is {},  traceId is {}", JSON.toJSONString(loginRequest), urlParam.get(AppClientConstants.TRACE_ID));
            context.setResult(HttpResult.ofFailed(ResultCodeEnum.OUTSIDE_REMOTE_ERROR));
            return null;
        }
        return authLoginResponse;
    }

