@Override
    public void generatePhoneLoginVerification(String mobile, ShortMessageTypeEnum verificationType, LocalDateTime currentTime) {
        notBlank(mobile, "Mobile is required!");
        notNull(verificationType, "verificationType is required!");
        notNull(currentTime, "Current time is required!");
        /**
         * 校验数据库记录，生成验证码
         */
        VerificationE shortMessageVerification = createShortMessageVerification(mobile, verificationType, currentTime);
        /**
         * 生成验证码发送模板
         */
        CommunicationEventMessage communicationEventMessage = buildCommunicationEventMessage(shortMessageVerification.getVerificationCode(), verificationType,
                shortMessageVerification.getAccountNo());
        /**
         * 发送短信
         */
        externalCommunicationService.sendMessage(communicationEventMessage);
    }

protected VerificationE createShortMessageVerification(String mobile, ShortMessageTypeEnum shortMessageTypeEnum, LocalDateTime currentTime) {
        /**
         * 查询一个小时内发送的有效记录
         */
        LocalDateTime startTime = currentTime.minus(VERIFICATION_EFFECTIVE_PERIOD);
        List<VerificationE> verifications = verificationRepository.findByAccountNoAndStatus(mobile, shortMessageTypeEnum.getCode(), VerificationStatusEnum.GENERATED.getCode(), startTime, currentTime);
        /**
         * 一个小时内重复发送次数超过
         */
        if (!isEmpty(verifications) && verifications.size() >= VERIFICATION_MAX_TIME) {
            log.warn("Verification code generated too many times for this mobile {}: times", mobile, verifications.size());
            throw new BizException("获取短信验证码次数超出限制，请稍后再试");
        }
        /**
         * 不存在验证码或者一个小时内发送次数没超过限制，就生成验证码发送
         */
        String verifyText = RandomStringUtils.randomNumeric(verificationCodeLength);
        VerificationE verificationE = new VerificationE(mobile, VerificationAccountTypeEnum.PHONE.getCode(), verifyText, shortMessageTypeEnum.getCode(), currentTime);
        verificationE.save();
        return verificationE;

    }

private TokenInfoVO convertAuthLoginResponseToTokenInfoVO(GatewayContext context, Response<AuthLoginResponse> authLoginResponse) {
        if (authLoginResponse == null) {
            return null;
        }
        // 前端要求特殊处理第一次登录用户 返回空信息给前端
        if (ResponseStatus.SUCCESS.equals(authLoginResponse.getStatus())
                && Objects.isNull(authLoginResponse.getContent())) {
            context.setResult(HttpResult.ofSuccess(new TokenInfoVO()));
            return null;
        }
        if (ResponseStatus.FAILED.equals(authLoginResponse.getStatus())
                || Objects.isNull(authLoginResponse.getContent()) || Objects.isNull(authLoginResponse.getContent().getUserId())) {
            context.setResult(HttpResult.ofFailed(ResultCodeEnum.LOGIN_FAILED));
            return null;
        }

        //初始化 token信息
        TokenInfoVO tokenInfoVO = new TokenInfoVO();
        tokenInfoVO.setUserId(authLoginResponse.getContent().getUserId());
        tokenInfoVO.setCertificationStatus(authLoginResponse.getContent().getIsAuthenticated() ? 1 : 0);
        tokenInfoVO.setExternalUserId(authLoginResponse.getContent().getExternalUserId());
        Map<String, String> extendInfoMap = new HashMap<>();
        extendInfoMap.put(TokenExtendInfoEnum.USER_AVATAR.getExtendName(), authLoginResponse.getContent().getUserAvatar());
        extendInfoMap.put(TokenExtendInfoEnum.NICK_NAME.getExtendName(), authLoginResponse.getContent().getUserNickName());
        extendInfoMap.put(TokenExtendInfoEnum.MOBILE.getExtendName(), authLoginResponse.getContent().getMobile());
        tokenInfoVO.setExtendInfo(extendInfoMap);
        return tokenInfoVO;
    }

